mapper.select:
SELECT A.BOOKSET_ID AS booksetId, B.BOOKSET_NAME AS booksetName, A.PARAM_CODE AS paramCode, A.PARAM_VALUE AS paramValue, A.PARAM_NAME AS paramName, A.PARAM_TYPE AS paramType, A.REMARK AS remark FROM BOK_BOOKSET_EXT A LEFT JOIN BOK_BOOKSET B ON A.BOOKSET_ID = B.BOOKSET_ID WHERE 1=1
AND B.BOOKSET_TYPE = '02'
AND A.BOOKSET_ID=#{booksetId}
AND A.PARAM_CODE=#{paramCode}
AND A.PARAM_TYPE=#{paramType}
ORDER BY A.BOOKSET_ID,A.PARAM_CODE
